window.TIMELINE = {"fps": 25, "scenes": [{"id": "hook", "title": "L'accroche", "start": 0.0, "beats": [{"id": "h_24", "start": 1.2, "sentences": [{"start": 1.2, "end": 3.594, "text": "Prenons un cabinet de gestion de patrimoine fictif."}, {"start": 3.874, "end": 12.072, "text": "Il passe environ vingt-quatre heures par semaine à rechercher des informations, préparer des rendez-vous, vérifier des pièces et reconstruire ses suivis clients."}], "end": 12.072}, {"id": "h_10", "start": 12.497, "sentences": [{"start": 12.497, "end": 20.265, "text": "Sur ces vingt-quatre heures, notre hypothèse est qu'il pourrait en récupérer dix, sans laisser une intelligence artificielle conseiller à la place du CGP."}], "end": 20.265}, {"id": "h_460", "start": 20.775, "sentences": [{"start": 20.775, "end": 27.926, "text": "Dix heures par semaine, sur quarante-six semaines travaillées, cela représente quatre cent soixante heures de capacité potentielle sur une année."}], "end": 27.926}, {"id": "h_notca", "start": 28.351, "sentences": [{"start": 28.351, "end": 30.776, "text": "Ce n'est pas du chiffre d'affaires supplémentaire promis."}, {"start": 31.056, "end": 38.415, "text": "C'est du temps que le cabinet pourrait consacrer à ses clients, à ses dossiers ou à son développement, si les mesures du pilote confirment l'hypothèse."}], "end": 38.415}, {"id": "h_cond", "start": 39.01, "sentences": [{"start": 39.01, "end": 40.275, "text": "Mais il y a une condition."}, {"start": 40.555, "end": 48.753, "text": "Dès qu'on touche à des situations patrimoniales, à des documents d'identité ou à des échanges privés, on ne branche pas simplement un chatbot sur tous les fichiers du cabinet."}], "end": 48.753}, {"id": "h_mission", "start": 49.348, "sentences": [{"start": 49.348, "end": 54.837, "text": "Aujourd'hui, on va suivre une mission, du premier diagnostic jusqu'à la décision de déployer ou d'arrêter."}], "end": 54.837}, {"id": "h_plan", "start": 55.177, "sentences": [{"start": 55.177, "end": 63.498, "text": "On va noter le fonctionnement du cabinet, voir où passe son temps, puis mettre trois agents au travail, avec un CGP qui garde la main à chaque étape."}], "end": 63.498}], "end": 64.178}, {"id": "title", "title": "Titre", "start": 64.178, "beats": [{"id": "t_disc", "start": 64.978, "sentences": [{"start": 64.978, "end": 68.855, "text": "Précision avant de commencer : ceci est une simulation pédagogique."}, {"start": 69.135, "end": 73.333, "text": "Le cabinet, les personnes, les dossiers et les chiffres sont fictifs."}], "end": 73.333}], "end": 74.523}, {"id": "cabinet", "title": "Le cabinet que l'on audite", "start": 74.523, "beats": [{"id": "c_name", "start": 75.123, "sentences": [{"start": 75.123, "end": 77.641, "text": "Notre cabinet fictif s'appelle Horizon Patrimoine."}, {"start": 77.921, "end": 80.578, "text": "Il est installé à Aix-en-Provence et compte trois personnes."}], "end": 80.578}, {"id": "c_sophie", "start": 81.003, "sentences": [{"start": 81.003, "end": 82.397, "text": "Sophie dirige le cabinet."}, {"start": 82.677, "end": 88.085, "text": "Elle conduit les rendez-vous patrimoniaux, prend les décisions de conseil et valide les communications importantes."}], "end": 88.085}, {"id": "c_karim", "start": 88.425, "sentences": [{"start": 88.425, "end": 89.477, "text": "Karim est conseiller."}, {"start": 89.757, "end": 94.067, "text": "Il prépare les dossiers, suit une partie des clients et réalise des rendez-vous."}], "end": 94.067}, {"id": "c_lea", "start": 94.407, "sentences": [{"start": 94.407, "end": 99.721, "text": "Léa coordonne l'accueil, l'agenda, les demandes de pièces et le suivi administratif."}, {"start": 100.001, "end": 102.052, "text": "Elle travaille quatre jours par semaine."}], "end": 102.052}, {"id": "c_180", "start": 102.477, "sentences": [{"start": 102.477, "end": 108.814, "text": "Dans notre simulation, le cabinet suit environ cent quatre-vingts foyers clients et reçoit régulièrement de nouveaux prospects."}], "end": 108.814}, {"id": "c_statut", "start": 109.154, "sentences": [{"start": 109.154, "end": 117.039, "text": "On ne suppose aucun statut réglementaire unique : une vraie mission vérifierait les statuts du cabinet, ses prestations et ses procédures."}], "end": 117.039}, {"id": "c_tools", "start": 117.549, "sentences": [{"start": 117.549, "end": 124.271, "text": "L'équipe utilise un CRM, une messagerie, un agenda, un espace documentaire et des modèles de documents."}, {"start": 124.551, "end": 125.937, "text": "Les outils existent."}, {"start": 126.217, "end": 128.963, "text": "Le problème, ce sont les passages de l'un à l'autre."}], "end": 128.963}, {"id": "c_before", "start": 129.388, "sentences": [{"start": 129.388, "end": 139.685, "text": "Avant un rendez-vous, Sophie retrouve une note dans le CRM, cherche le dernier échange dans sa messagerie, ouvre les pièces dans un dossier partagé et vérifie si une action promise a été faite."}], "end": 139.685}, {"id": "c_after", "start": 140.025, "sentences": [{"start": 140.025, "end": 145.249, "text": "Après le rendez-vous, elle refait une partie du chemin pour rédiger le compte rendu et organiser la suite."}], "end": 145.249}, {"id": "c_relay", "start": 145.589, "sentences": [{"start": 145.589, "end": 148.084, "text": "C'est sur ces passages de relais que porte notre audit."}], "end": 148.084}], "end": 148.849}, {"id": "audit", "title": "L'audit, avant de parler d'agents", "start": 148.849, "beats": [{"id": "a_people", "start": 149.449, "sentences": [{"start": 149.449, "end": 153.363, "text": "La mission commence avec les personnes, pas avec une démonstration d'IA."}], "end": 153.363}, {"id": "a_show", "start": 153.618, "sentences": [{"start": 153.618, "end": 157.428, "text": "Pendant le diagnostic, on demande à chacun de montrer un dossier de bout en bout."}], "end": 157.428}, {"id": "a_q", "start": 157.683, "sentences": [{"start": 157.683, "end": 158.973, "text": "Comment arrive une demande ?"}, {"start": 159.253, "end": 160.619, "text": "Quelles sources sont consultées ?"}, {"start": 160.899, "end": 162.44, "text": "Qui repère une pièce manquante ?"}, {"start": 162.72, "end": 163.943, "text": "Qui valide le compte rendu ?"}, {"start": 164.223, "end": 165.612, "text": "Où voit-on la prochaine action ?"}], "end": 165.612}, {"id": "a_cols", "start": 166.037, "sentences": [{"start": 166.037, "end": 171.913, "text": "On distingue ce que l'équipe déclare faire, ce qu'on peut observer dans les outils, et ce qu'il faudra mesurer pendant le pilote."}], "end": 171.913}, {"id": "a_split", "start": 172.423, "sentences": [{"start": 172.423, "end": 180.158, "text": "On répartit ensuite vingt-quatre heures hebdomadaires de travail répétitif en trois blocs, sans compter deux fois la même tâche."}], "end": 180.158}, {"id": "a_8", "start": 180.413, "sentences": [{"start": 180.413, "end": 186.137, "text": "Huit heures pour préparer les rendez-vous, rassembler le contexte et remettre les notes en forme après l'échange."}], "end": 186.137}, {"id": "a_9", "start": 186.307, "sentences": [{"start": 186.307, "end": 191.679, "text": "Neuf heures pour rechercher les pièces, vérifier des listes de contrôle et préparer les revues de dossiers."}], "end": 191.679}, {"id": "a_7", "start": 191.849, "sentences": [{"start": 191.849, "end": 197.759, "text": "Sept heures pour retrouver les engagements, rédiger des brouillons de suivi et préparer les priorités de la semaine."}], "end": 197.759}, {"id": "a_sum", "start": 198.014, "sentences": [{"start": 198.014, "end": 200.489, "text": "Huit plus neuf plus sept : vingt-quatre heures."}, {"start": 200.769, "end": 202.456, "text": "Ce sont des hypothèses de départ."}, {"start": 202.736, "end": 208.715, "text": "Dans un vrai cabinet, il faudrait chronométrer un échantillon de tâches et tenir compte des différences entre dossiers."}], "end": 208.715}, {"id": "a_grid", "start": 209.31, "sentences": [{"start": 209.31, "end": 213.173, "text": "On note aussi le fonctionnement du cabinet sur cinq critères, chacun sur vingt."}], "end": 213.173}, {"id": "a_s1", "start": 213.428, "sentences": [{"start": 213.428, "end": 215.427, "text": "Processus : treize sur vingt."}, {"start": 215.707, "end": 218.745, "text": "L'équipe connaît les étapes, mais elles sont peu documentées."}], "end": 218.745}, {"id": "a_s2", "start": 218.915, "sentences": [{"start": 218.915, "end": 221.178, "text": "Interconnexion des outils : six sur vingt."}, {"start": 221.458, "end": 224.354, "text": "Plusieurs informations doivent être recherchées et ressaisies."}], "end": 224.354}, {"id": "a_s3", "start": 224.524, "sentences": [{"start": 224.524, "end": 227.433, "text": "Maîtrise des accès et des données : sept sur vingt."}, {"start": 227.713, "end": 230.833, "text": "Les règles d'usage des outils d'IA restent à préciser."}], "end": 230.833}, {"id": "a_s4", "start": 231.003, "sentences": [{"start": 231.003, "end": 233.567, "text": "Appropriation par l'équipe : neuf sur vingt."}, {"start": 233.847, "end": 237.491, "text": "Chacun est intéressé, personne n'a encore testé un workflow complet."}], "end": 237.491}, {"id": "a_s5", "start": 237.661, "sentences": [{"start": 237.661, "end": 240.748, "text": "Validations et traçabilité : dix sur vingt."}, {"start": 241.028, "end": 245.513, "text": "Les décisions humaines existent, mais leur historique est difficile à retrouver."}], "end": 245.513}, {"id": "a_45", "start": 245.853, "sentences": [{"start": 245.853, "end": 247.915, "text": "Total : quarante-cinq sur cent."}], "end": 247.915}, {"id": "a_not", "start": 248.51, "sentences": [{"start": 248.51, "end": 255.065, "text": "Ce n'est pas une mesure du professionnalisme des conseillers, mais la photographie fictive d'un système de travail, selon notre grille."}, {"start": 255.345, "end": 258.023, "text": "La mission devra rendre chaque critère vérifiable."}], "end": 258.023}, {"id": "a_map", "start": 258.618, "sentences": [{"start": 258.618, "end": 263.455, "text": "On range ensuite les tâches observées dans les cinq domaines de la cartographie Agentic Wealth."}], "end": 263.455}, {"id": "a_d1", "start": 263.71, "sentences": [{"start": 263.71, "end": 268.149, "text": "Acquisition et conversion : prospects, premiers rendez-vous, relances."}], "end": 268.149}, {"id": "a_d2", "start": 268.319, "sentences": [{"start": 268.319, "end": 271.996, "text": "Conseil et préparation : briefs, comptes rendus, questions à poser."}], "end": 271.996}, {"id": "a_d3", "start": 272.166, "sentences": [{"start": 272.166, "end": 277.337, "text": "Conformité et traçabilité : pièces, listes de contrôle, journaux de validation."}], "end": 277.337}, {"id": "a_d4", "start": 277.507, "sentences": [{"start": 277.507, "end": 282.193, "text": "Service et relation client : demandes entrantes, engagements, réponses."}], "end": 282.193}, {"id": "a_d5", "start": 282.363, "sentences": [{"start": 282.363, "end": 286.973, "text": "Pilotage du cabinet : priorités, échéances, dossiers sans action récente."}], "end": 286.973}, {"id": "a_rule", "start": 287.313, "sentences": [{"start": 287.313, "end": 291.342, "text": "Partout, la même règle : l'agent prépare, le conseiller décide."}, {"start": 291.622, "end": 294.493, "text": "Voyons trois agents à l'œuvre, sur une semaine type."}], "end": 294.493}], "end": 295.343}, {"id": "agent1", "title": "Agent 1 : préparer le rendez-vous et sa suite", "start": 295.343, "beats": [{"id": "p_intro", "start": 296.143, "sentences": [{"start": 296.143, "end": 297.167, "text": "Première scène."}, {"start": 297.447, "end": 299.34, "text": "Mardi, huit heures trente-cinq."}, {"start": 299.62, "end": 303.965, "text": "Sophie a un rendez-vous de suivi à quatorze heures avec Camille, une cliente fictive."}], "end": 303.965}, {"id": "p_today", "start": 304.305, "sentences": [{"start": 304.305, "end": 311.891, "text": "Sans agent, elle ouvre le CRM, cherche le dernier compte rendu, relit trois échanges, vérifie les documents et note ses questions."}, {"start": 312.171, "end": 315.986, "text": "Après le rendez-vous, elle rédige le compte rendu et crée les actions."}], "end": 315.986}, {"id": "p_today2", "start": 316.241, "sentences": [{"start": 316.241, "end": 319.073, "text": "Cette chaîne pèse lourd dans les huit heures du premier bloc."}], "end": 319.073}, {"id": "p_path", "start": 319.498, "sentences": [{"start": 319.498, "end": 323.345, "text": "Voici le parcours à tester : onze étapes, dont trois validations humaines."}], "end": 323.345}, {"id": "p_1", "start": 323.77, "sentences": [{"start": 323.77, "end": 326.436, "text": "Étape un : Sophie sélectionne elle-même le rendez-vous."}, {"start": 326.716, "end": 328.426, "text": "L'agent ne choisit pas seul les dossiers."}], "end": 328.426}, {"id": "p_2", "start": 328.766, "sentences": [{"start": 328.766, "end": 338.973, "text": "Étape deux : elle autorise les sources utiles pour ce dossier : fiche CRM, comptes rendus validés, échanges professionnels pertinents, documents auxquels elle est habilitée à accéder."}], "end": 338.973}, {"id": "p_2b", "start": 339.228, "sentences": [{"start": 339.228, "end": 344.584, "text": "Une archive ancienne et la messagerie complète restent grisées : elles sont hors périmètre."}], "end": 344.584}, {"id": "p_3", "start": 344.924, "sentences": [{"start": 344.924, "end": 346.706, "text": "Étape trois : la collecte."}, {"start": 346.986, "end": 350.6, "text": "L'agent ne lit que ces sources, et garde l'origine de chaque information."}], "end": 350.6}, {"id": "p_4", "start": 350.855, "sentences": [{"start": 350.855, "end": 352.758, "text": "Étape quatre : le rapprochement."}, {"start": 353.038, "end": 358.741, "text": "La fiche CRM indique une dernière revue le douze mars, le compte rendu validé le quatorze mars."}, {"start": 359.021, "end": 361.676, "text": "L'agent ne choisit pas : il signale l'écart."}], "end": 361.676}, {"id": "p_5", "start": 362.016, "sentences": [{"start": 362.016, "end": 363.823, "text": "Étape cinq : les manques."}, {"start": 364.103, "end": 371.423, "text": "Un justificatif introuvable, une échéance citée dans un échange mais absente du suivi, une information vieille de deux ans."}, {"start": 371.703, "end": 373.663, "text": "Chaque point est listé avec sa source."}], "end": 373.663}, {"id": "p_6", "start": 374.003, "sentences": [{"start": 374.003, "end": 375.721, "text": "Étape six : le brief."}, {"start": 376.001, "end": 383.611, "text": "En haut, les faits sourcés : dernier échange, objectifs exprimés par la cliente, actions convenues, documents disponibles."}, {"start": 383.891, "end": 385.732, "text": "Plus bas, les points à vérifier."}], "end": 385.732}, {"id": "p_6q", "start": 385.987, "sentences": [{"start": 385.987, "end": 393.934, "text": "Puis des questions pour l'entretien, comme : « L'objectif formulé au dernier rendez-vous est-il toujours d'actualité ? » Une question aide la conversation."}, {"start": 394.214, "end": 396.63, "text": "Elle ne conclut rien sur la situation de Camille."}], "end": 396.63}, {"id": "p_7", "start": 396.97, "sentences": [{"start": 396.97, "end": 398.85, "text": "Étape sept : la correction."}, {"start": 399.13, "end": 400.89, "text": "Sophie voit d'où vient chaque élément."}, {"start": 401.17, "end": 406.536, "text": "Elle retire une question peu pertinente, corrige la date de la dernière revue, puis valide sa version."}, {"start": 406.816, "end": 410.002, "text": "C'est Sophie qui mène le rendez-vous et interprète les réponses."}], "end": 410.002}, {"id": "p_8", "start": 410.427, "sentences": [{"start": 410.427, "end": 414.012, "text": "Étape huit : le rendez-vous, de quatorze heures à quinze heures dix."}, {"start": 414.292, "end": 418.87, "text": "Pas d'écran d'IA : la conversation appartient à la cliente et à sa conseillère."}], "end": 418.87}, {"id": "p_9", "start": 419.465, "sentences": [{"start": 419.465, "end": 422.209, "text": "Étape neuf : le brouillon de compte rendu."}, {"start": 422.489, "end": 428.519, "text": "À quinze heures dix, Sophie saisit ses notes, ou une transcription si celle-ci est autorisée et encadrée."}], "end": 428.519}, {"id": "p_9b", "start": 428.774, "sentences": [{"start": 428.774, "end": 437.048, "text": "L'agent sépare quatre choses : les faits rapportés par la cliente, les questions ouvertes, les décisions réellement prises par Sophie, et les actions proposées."}], "end": 437.048}, {"id": "p_9c", "start": 437.303, "sentences": [{"start": 437.303, "end": 440.599, "text": "Il signale une phrase ambiguë : « revoir le dossier le mois prochain »."}, {"start": 440.879, "end": 443.35, "text": "Revoir quoi, avec qui, à quelle date ?"}, {"start": 443.63, "end": 445.674, "text": "Il ne complète pas la promesse de lui-même."}], "end": 445.674}, {"id": "p_10", "start": 446.014, "sentences": [{"start": 446.014, "end": 447.949, "text": "Étape dix : la validation."}, {"start": 448.229, "end": 453.032, "text": "Sophie précise : un point téléphonique dans quatre semaines, qu'elle mènera elle-même."}, {"start": 453.312, "end": 454.736, "text": "Puis elle valide le compte rendu."}], "end": 454.736}, {"id": "p_11", "start": 455.076, "sentences": [{"start": 455.076, "end": 457.64, "text": "Étape onze : les tâches et le suivi."}, {"start": 457.92, "end": 461.988, "text": "L'agent propose deux tâches, avec responsable et échéance à confirmer."}, {"start": 462.268, "end": 466.062, "text": "Une fois validées par Sophie, elles rejoignent l'outil de suivi autorisé."}], "end": 466.062}, {"id": "p_11b", "start": 466.317, "sentences": [{"start": 466.317, "end": 468.644, "text": "Un message à Camille reste un brouillon."}, {"start": 468.924, "end": 472.073, "text": "Sophie contrôle le destinataire, le contenu et l'envoi."}, {"start": 472.353, "end": 473.846, "text": "Rien ne part sans son clic."}], "end": 473.846}, {"id": "p_gain", "start": 474.271, "sentences": [{"start": 474.271, "end": 478.86, "text": "Sur les huit heures de ce bloc, l'objectif de test est d'en récupérer quatre."}, {"start": 479.14, "end": 481.34, "text": "C'est un gain cible, pas un résultat."}], "end": 481.34}, {"id": "p_measure", "start": 481.595, "sentences": [{"start": 481.595, "end": 486.606, "text": "On mesurera le temps avant et après, les corrections, les erreurs, et l'utilité réelle des briefs."}], "end": 486.606}, {"id": "p_jalon", "start": 486.861, "sentences": [{"start": 486.861, "end": 491.524, "text": "Premier jalon, volontairement petit : trois briefs, puis une décision de Sophie."}, {"start": 491.804, "end": 494.359, "text": "Continuer, ajuster, ou retirer l'accès."}], "end": 494.359}], "end": 495.209}, {"id": "agent2", "title": "Agent 2 : voir les manques, sans déclarer un dossier conforme", "start": 495.209, "beats": [{"id": "d_intro", "start": 496.009, "sentences": [{"start": 496.009, "end": 497.056, "text": "Deuxième scène."}, {"start": 497.336, "end": 498.581, "text": "Mercredi, dix heures vingt."}, {"start": 498.861, "end": 502.879, "text": "Léa prépare plusieurs dossiers pour des rendez-vous et une revue périodique."}], "end": 502.879}, {"id": "d_today", "start": 503.134, "sentences": [{"start": 503.134, "end": 511.016, "text": "Elle parcourt les répertoires, compare les fichiers aux listes du cabinet, cherche des dates, et fait trancher les cas incertains par Sophie ou Karim."}], "end": 511.016}, {"id": "d_9", "start": 511.271, "sentences": [{"start": 511.271, "end": 514.994, "text": "Dans notre simulation, ce travail représente neuf heures par semaine."}], "end": 514.994}, {"id": "d_limit", "start": 515.419, "sentences": [{"start": 515.419, "end": 518.565, "text": "Première limite : l'agent n'invente pas les règles de contrôle."}, {"start": 518.845, "end": 522.762, "text": "La liste applicable vient du cabinet, validée par la personne compétente."}], "end": 522.762}, {"id": "d_frame", "start": 523.017, "sentences": [{"start": 523.017, "end": 531.4, "text": "On vérifie aussi le cadre d'accès aux données : quelles sources, quelles personnes habilitées, quelle finalité, quel sous-traitant éventuel, quelle conservation."}], "end": 531.4}, {"id": "d_run", "start": 531.825, "sentences": [{"start": 531.825, "end": 542.606, "text": "Pour un dossier sélectionné, l'agent lit la liste approuvée, inventorie seulement les documents autorisés, et range chaque ligne en quatre colonnes : présent, absent, ambigu, ou non vérifié."}], "end": 542.606}, {"id": "d_amb", "start": 543.031, "sentences": [{"start": 543.031, "end": 547.091, "text": "Supposons un justificatif présent, mais dont la date est illisible."}, {"start": 547.371, "end": 549.905, "text": "L'agent ne le marque ni « valide », ni « périmé »."}, {"start": 550.185, "end": 554.68, "text": "Il le classe en ambigu, et montre le document source avec la raison du signalement."}], "end": 554.68}, {"id": "d_lea", "start": 554.935, "sentences": [{"start": 554.935, "end": 558.608, "text": "Léa retrouve une meilleure version, ou demande à Sophie quelle suite donner."}], "end": 558.608}, {"id": "d_review", "start": 559.033, "sentences": [{"start": 559.033, "end": 566.752, "text": "Pour une revue périodique, il compare avec la dernière revue : éléments nouveaux, inchangés, pièces à examiner, contrôles sans réponse."}], "end": 566.752}, {"id": "d_human", "start": 567.007, "sentences": [{"start": 567.007, "end": 572.465, "text": "Si une information essentielle manque, l'écran indique : décision humaine requise."}, {"start": 572.745, "end": 576.587, "text": "Jamais de badge « dossier conforme » sur la seule base de sa lecture."}], "end": 576.587}, {"id": "d_kyc", "start": 577.012, "sentences": [{"start": 577.012, "end": 580.295, "text": "C'est essentiel pour la connaissance client et la vigilance."}, {"start": 580.575, "end": 585.54, "text": "Selon les activités exercées, le professionnel applique les exigences qui lui sont propres."}], "end": 585.54}, {"id": "d_amf", "start": 585.795, "sentences": [{"start": 585.795, "end": 596.904, "text": "Pour le conseil en investissements financiers, l'AMF décrit notamment les informations à recueillir avant de conseiller, et la déclaration d'adéquation remise au client avant la réalisation de l'opération conseillée."}, {"start": 597.184, "end": 602.541, "text": "Pour les professionnels assujettis, les obligations de vigilance suivent une approche fondée sur les risques."}], "end": 602.541}, {"id": "d_nostat", "start": 602.796, "sentences": [{"start": 602.796, "end": 607.316, "text": "L'agent aide à préparer et à retrouver des éléments, sans statuer sur leur suffisance."}, {"start": 607.596, "end": 611.757, "text": "Et cette vidéo n'est pas un modèle universel de dossier réglementaire."}], "end": 611.757}, {"id": "d_log", "start": 612.182, "sentences": [{"start": 612.182, "end": 622.95, "text": "Après la revue, un journal conserve les sources consultées, la version du résultat, la correction de Léa, la validation de Sophie et l'horodatage, selon les règles de conservation du cabinet."}], "end": 622.95}, {"id": "d_lognot", "start": 623.205, "sentences": [{"start": 623.205, "end": 629.043, "text": "Mais un journal technique n'est pas, à lui seul, la preuve que les obligations réglementaires sont remplies."}], "end": 629.043}, {"id": "d_gain", "start": 629.468, "sentences": [{"start": 629.468, "end": 634.353, "text": "Hypothèse : ramener ce bloc de neuf à six heures par semaine, soit trois heures récupérées."}], "end": 634.353}, {"id": "d_measure", "start": 634.608, "sentences": [{"start": 634.608, "end": 640.819, "text": "Le pilote suivra aussi les faux positifs, les vrais manques détectés, et les situations correctement laissées à l'équipe."}], "end": 640.819}], "end": 641.669}, {"id": "agent3", "title": "Agent 3 : relation client et pilotage de la semaine", "start": 641.669, "beats": [{"id": "s_intro", "start": 642.469, "sentences": [{"start": 642.469, "end": 643.406, "text": "Troisième scène."}, {"start": 643.686, "end": 645.417, "text": "Jeudi, seize heures quarante."}, {"start": 645.697, "end": 649.726, "text": "Une cliente écrit : « Pouvez-vous me rappeler ce que nous avions convenu pour la suite ? »"}], "end": 649.726}, {"id": "s_today", "start": 649.981, "sentences": [{"start": 649.981, "end": 655.661, "text": "Léa cherche le dernier compte rendu, vérifie la tâche, puis demande à Karim si l'action est faite."}, {"start": 655.941, "end": 659.874, "text": "En parallèle, un prospect attend un retour et deux échéances approchent."}], "end": 659.874}, {"id": "s_class", "start": 660.214, "sentences": [{"start": 660.214, "end": 668.417, "text": "L'agent de service classe la demande, puis rassemble les seuls éléments autorisés : le message, le compte rendu validé, la tâche et son statut."}], "end": 668.417}, {"id": "s_card", "start": 668.672, "sentences": [{"start": 668.672, "end": 669.871, "text": "Il prépare une fiche."}, {"start": 670.151, "end": 671.624, "text": "Voici l'engagement retrouvé."}, {"start": 671.904, "end": 673.088, "text": "Voici sa source."}, {"start": 673.368, "end": 674.513, "text": "Voici l'état connu."}, {"start": 674.793, "end": 676.636, "text": "Et voici ce que nous ne savons pas encore."}], "end": 676.636}, {"id": "s_draft", "start": 676.976, "sentences": [{"start": 676.976, "end": 679.022, "text": "Il peut rédiger un brouillon de réponse."}, {"start": 679.302, "end": 684.123, "text": "Ici, la tâche n'a pas de statut fiable : le brouillon n'affirme donc pas qu'elle est terminée."}], "end": 684.123}, {"id": "s_karim", "start": 684.378, "sentences": [{"start": 684.378, "end": 687.407, "text": "Karim vérifie, complète, puis décide de l'envoi."}, {"start": 687.687, "end": 690.638, "text": "Seul Karim dispose du bouton « vérifier et envoyer »."}, {"start": 690.918, "end": 693.03, "text": "L'agent n'a qu'un bouton : « préparer »."}], "end": 693.03}, {"id": "s_prosp", "start": 693.455, "sentences": [{"start": 693.455, "end": 695.061, "text": "Même logique pour un prospect."}, {"start": 695.341, "end": 704.193, "text": "L'agent propose une fiche de qualification à partir du formulaire et des échanges autorisés, des questions pour un premier rendez-vous, et une relance contextualisée."}], "end": 704.193}, {"id": "s_noscore", "start": 704.448, "sentences": [{"start": 704.448, "end": 709.482, "text": "Le conseiller choisit de prendre contact, d'accepter ou non le prospect, et d'envoyer chaque message."}, {"start": 709.762, "end": 712.175, "text": "Aucun score automatique de « valeur » de la personne."}], "end": 712.175}, {"id": "s_monday", "start": 712.685, "sentences": [{"start": 712.685, "end": 716.742, "text": "Le lundi suivant, à neuf heures, Sophie ouvre une vue de pilotage."}], "end": 716.742}, {"id": "s_lists", "start": 716.997, "sentences": [{"start": 716.997, "end": 730.201, "text": "L'agent a rapproché agenda, tâches et statuts du CRM en quatre listes : rendez-vous à préparer, engagements sans responsable confirmé, échéances à vérifier, et dossiers sans action récente, selon une règle choisie par le cabinet."}], "end": 730.201}, {"id": "s_reason", "start": 730.456, "sentences": [{"start": 730.456, "end": 732.246, "text": "Chaque signal comporte une raison."}, {"start": 732.526, "end": 736.843, "text": "Un dossier sans activité récente n'est pas étiqueté « client négligé »."}], "end": 736.843}, {"id": "s_arb", "start": 737.098, "sentences": [{"start": 737.098, "end": 743.741, "text": "Sophie répond : « celui-ci attend volontairement une date », « celui-là mérite un appel », « cette donnée du CRM est incorrecte »."}, {"start": 744.021, "end": 745.302, "text": "C'est elle qui arbitre."}], "end": 745.302}, {"id": "s_gain", "start": 745.727, "sentences": [{"start": 745.727, "end": 750.713, "text": "Notre hypothèse : ramener ce bloc de sept à quatre heures par semaine, soit trois heures récupérées."}], "end": 750.713}, {"id": "s_measure", "start": 750.968, "sentences": [{"start": 750.968, "end": 756.302, "text": "On compte aussi les alertes utiles ou écartées, les brouillons corrigés et les engagements retrouvés."}, {"start": 756.582, "end": 762.546, "text": "Si le tableau produit du bruit, on réduit son périmètre : un cockpit que personne n'ouvre n'est pas un gain."}], "end": 762.546}], "end": 763.396}, {"id": "data", "title": "La question des données et des limites", "start": 763.396, "beats": [{"id": "x_q", "start": 764.196, "sentences": [{"start": 764.196, "end": 770.262, "text": "Sophie pose alors la bonne question : « Pour préparer tout ça, l'agent doit-il lire tous mes mails et tous mes dossiers ? »"}], "end": 770.262}, {"id": "x_no", "start": 770.602, "sentences": [{"start": 770.602, "end": 772.382, "text": "La réponse de la mission est non."}], "end": 772.382}, {"id": "x_flow", "start": 772.807, "sentences": [{"start": 772.807, "end": 779.288, "text": "Chaque workflow a un objectif défini, des sources approuvées, des droits limités et des personnes habilitées."}, {"start": 779.568, "end": 785.394, "text": "Source autorisée, accès limité, préparation, validation humaine, destination autorisée."}], "end": 785.394}, {"id": "x_check", "start": 785.734, "sentences": [{"start": 785.734, "end": 795.74, "text": "Avant d'utiliser des données clients, le cabinet examine ses responsabilités, ses contrats avec les prestataires, la sécurité, la conservation et les éventuels transferts."}], "end": 795.74}, {"id": "x_host", "start": 795.995, "sentences": [{"start": 795.995, "end": 802.019, "text": "Héberger un modèle soi-même, ou choisir un modèle open source, ne suffit pas à rendre un traitement conforme."}, {"start": 802.299, "end": 808.82, "text": "La CNIL rappelle notamment l'importance d'encadrer la sous-traitance, de protéger les données et de garder une intervention humaine adaptée."}], "end": 808.82}, {"id": "x_stop", "start": 809.245, "sentences": [{"start": 809.245, "end": 811.116, "text": "Concrètement, l'agent sait s'arrêter."}], "end": 811.116}, {"id": "x_s1", "start": 811.371, "sentences": [{"start": 811.371, "end": 815.856, "text": "S'il ne retrouve pas la source d'un fait, il écrit : information non vérifiée."}], "end": 815.856}, {"id": "x_s2", "start": 816.026, "sentences": [{"start": 816.026, "end": 819.215, "text": "Si une pièce est illisible, il demande une vérification."}], "end": 819.215}, {"id": "x_s3", "start": 819.385, "sentences": [{"start": 819.385, "end": 825.257, "text": "Si une demande implique une interprétation patrimoniale ou une décision de conseil, il la transmet au CGP."}], "end": 825.257}, {"id": "x_never", "start": 825.597, "sentences": [{"start": 825.597, "end": 827.34, "text": "Il ne recommande aucun produit."}, {"start": 827.62, "end": 830.089, "text": "Il ne détermine pas seul un profil de risque."}, {"start": 830.369, "end": 832.382, "text": "Il ne déclare pas un dossier conforme."}, {"start": 832.662, "end": 834.693, "text": "Il ne contacte personne automatiquement."}, {"start": 834.973, "end": 837.682, "text": "Il ne modifie pas un engagement client sans validation."}], "end": 837.682}, {"id": "x_demo", "start": 838.107, "sentences": [{"start": 838.107, "end": 843.027, "text": "C'est pourquoi un vrai déploiement commence avec des données de démonstration et un accès limité."}, {"start": 843.307, "end": 848.4, "text": "Les données réelles arrivent seulement après revue du cadre applicable et autorisation du cabinet."}], "end": 848.4}], "end": 849.25}, {"id": "bilan", "title": "Le bilan chiffré", "start": 849.25, "beats": [{"id": "b_intro", "start": 850.05, "sentences": [{"start": 850.05, "end": 853.647, "text": "Reprenons nos chiffres, sans additionner des promesses incompatibles."}], "end": 853.647}, {"id": "b_1", "start": 853.987, "sentences": [{"start": 853.987, "end": 857.884, "text": "Préparation des rendez-vous et suivi : huit heures avant, quatre visées après."}, {"start": 858.164, "end": 859.302, "text": "Quatre heures à confirmer."}], "end": 859.302}, {"id": "b_2", "start": 859.557, "sentences": [{"start": 859.557, "end": 862.417, "text": "Contrôles et revues : neuf heures avant, six visées."}, {"start": 862.697, "end": 863.874, "text": "Trois heures à confirmer."}], "end": 863.874}, {"id": "b_3", "start": 864.129, "sentences": [{"start": 864.129, "end": 868.456, "text": "Relation client et pilotage : sept heures avant, quatre visées."}, {"start": 868.736, "end": 869.913, "text": "Trois heures à confirmer."}], "end": 869.913}, {"id": "b_sum", "start": 870.253, "sentences": [{"start": 870.253, "end": 873.348, "text": "Avant : huit plus neuf plus sept, vingt-quatre heures."}, {"start": 873.628, "end": 876.633, "text": "Après, visé : quatre plus six plus quatre, quatorze heures."}, {"start": 876.913, "end": 879.447, "text": "L'écart visé : dix heures par semaine."}], "end": 879.447}, {"id": "b_cap", "start": 879.787, "sentences": [{"start": 879.787, "end": 884.188, "text": "Dix heures de capacité potentielle, à condition que les gains résistent à l'observation."}, {"start": 884.468, "end": 886.368, "text": "La mesure réelle reste à établir."}], "end": 886.368}, {"id": "b_460", "start": 886.708, "sentences": [{"start": 886.708, "end": 892.023, "text": "Sur une année, dix heures multipliées par quarante-six semaines travaillées donnent quatre cent soixante heures."}], "end": 892.023}, {"id": "b_euro", "start": 892.363, "sentences": [{"start": 892.363, "end": 901.141, "text": "À titre d'illustration seulement, avec une heure interne valorisée à soixante euros, cela représenterait vingt-sept mille six cents euros de capacité théorique annuelle."}], "end": 901.141}, {"id": "b_not", "start": 901.481, "sentences": [{"start": 901.481, "end": 905.687, "text": "Ce n'est ni une économie de trésorerie acquise, ni un revenu additionnel."}, {"start": 905.967, "end": 910.84, "text": "Capacité théorique, économies encaissées et chiffre d'affaires sont trois choses différentes."}], "end": 910.84}, {"id": "b_minus", "start": 911.095, "sentences": [{"start": 911.095, "end": 916.715, "text": "Il faut encore déduire le temps de contrôle humain, le coût des outils, la maintenance et les erreurs à corriger."}], "end": 916.715}], "end": 917.565}, {"id": "deploy", "title": "Déploiement et conclusion", "start": 917.565, "beats": [{"id": "y_first", "start": 918.365, "sentences": [{"start": 918.365, "end": 919.923, "text": "Quel agent déployer en premier ?"}, {"start": 920.203, "end": 927.673, "text": "Ici, je commencerais par la préparation d'un rendez-vous, sur trois briefs : un périmètre étroit, compréhensible par Sophie, et mesurable."}], "end": 927.673}, {"id": "y_order", "start": 927.928, "sentences": [{"start": 927.928, "end": 937.383, "text": "Si les briefs sont utiles et les accès maîtrisés, on ajoute le compte rendu et les tâches, puis les contrôles documentaires, et enfin la relation client et le cockpit."}], "end": 937.383}, {"id": "y_plan", "start": 937.808, "sentences": [{"start": 937.808, "end": 939.462, "text": "Voici le planning proposé."}], "end": 939.462}, {"id": "y_w12", "start": 939.717, "sentences": [{"start": 939.717, "end": 946.311, "text": "Semaines un et deux : diagnostic réel, chronométrage, cartographie des données, et choix d'un seul cas d'usage."}], "end": 946.311}, {"id": "y_w35", "start": 946.566, "sentences": [{"start": 946.566, "end": 954.538, "text": "Semaines trois à cinq : construction et test du premier workflow, d'abord sur des données fictives, puis sur un périmètre autorisé."}, {"start": 954.818, "end": 957.465, "text": "Trois briefs, relus intégralement par Sophie."}], "end": 957.465}, {"id": "y_w68", "start": 957.72, "sentences": [{"start": 957.72, "end": 961.923, "text": "Semaines six à huit : décision d'étendre, d'ajuster ou d'arrêter."}, {"start": 962.203, "end": 967.478, "text": "Les autres agents n'entrent dans le pilote que si le premier a fait ses preuves et si leurs accès sont approuvés."}], "end": 967.478}, {"id": "y_not3", "start": 967.733, "sentences": [{"start": 967.733, "end": 971.294, "text": "Huit semaines ne promettent donc pas trois agents achevés dans tous les cabinets."}], "end": 971.294}, {"id": "y_goal", "start": 971.889, "sentences": [{"start": 971.889, "end": 978.141, "text": "Le résultat recherché n'est pas un cabinet où l'intelligence artificielle parle à la place du conseiller."}, {"start": 978.421, "end": 984.328, "text": "C'est un cabinet où le conseiller retrouve le contexte, voit les manques, et décide avec moins de recherches dispersées."}], "end": 984.328}, {"id": "y_cta", "start": 984.838, "sentences": [{"start": 984.838, "end": 992.421, "text": "Si vous dirigez un cabinet de gestion de patrimoine, le point de départ est simple : montrez-nous un dossier et une semaine réelle."}], "end": 992.421}, {"id": "y_cta2", "start": 992.676, "sentences": [{"start": 992.676, "end": 999.139, "text": "On identifiera ce qui mérite d'être préparé, ce qui doit rester humain, et ce qu'un pilote permettrait réellement de mesurer."}], "end": 999.139}, {"id": "y_end", "start": 999.819, "sentences": [{"start": 999.819, "end": 1001.085, "text": "Agentic Wealth."}, {"start": 1001.365, "end": 1002.34, "text": "L'agent prépare."}, {"start": 1002.62, "end": 1004.738, "text": "Le CGP valide et décide."}], "end": 1004.738}], "end": 1007.713}], "cues": [{"start": 1.2, "end": 3.834, "lines": ["Prenons un cabinet de gestion", "de patrimoine fictif."]}, {"start": 3.874, "end": 7.922, "lines": ["Il passe environ vingt-quatre heures", "par semaine à rechercher des informations,"]}, {"start": 7.922, "end": 12.322, "lines": ["préparer des rendez-vous, vérifier des", "pièces et reconstruire ses suivis clients."]}, {"start": 12.497, "end": 16.356, "lines": ["Sur ces vingt-quatre heures, notre", "hypothèse est qu'il pourrait en récupérer"]}, {"start": 16.356, "end": 20.515, "lines": ["dix, sans laisser une intelligence", "artificielle conseiller à la place du CGP."]}, {"start": 20.775, "end": 24.102, "lines": ["Dix heures par semaine, sur quarante-six", "semaines travaillées, cela"]}, {"start": 24.102, "end": 28.176, "lines": ["représente quatre cent soixante heures", "de capacité potentielle sur une année."]}, {"start": 28.351, "end": 31.016, "lines": ["Ce n'est pas du chiffre", "d'affaires supplémentaire promis."]}, {"start": 31.056, "end": 34.883, "lines": ["C'est du temps que le cabinet pourrait", "consacrer à ses clients, à ses dossiers"]}, {"start": 34.883, "end": 38.665, "lines": ["ou à son développement, si les mesures", "du pilote confirment l'hypothèse."]}, {"start": 39.01, "end": 40.515, "lines": ["Mais il y a une condition."]}, {"start": 40.555, "end": 42.83, "lines": ["Dès qu'on touche", "à des situations patrimoniales,"]}, {"start": 42.83, "end": 45.294, "lines": ["à des documents d'identité", "ou à des échanges privés,"]}, {"start": 45.294, "end": 49.003, "lines": ["on ne branche pas simplement un chatbot", "sur tous les fichiers du cabinet."]}, {"start": 49.348, "end": 51.335, "lines": ["Aujourd'hui,", "on va suivre une mission,"]}, {"start": 51.335, "end": 55.087, "lines": ["du premier diagnostic jusqu'à", "la décision de déployer ou d'arrêter."]}, {"start": 55.177, "end": 59.9, "lines": ["On va noter le fonctionnement du cabinet,", "voir où passe son temps, puis mettre trois"]}, {"start": 59.9, "end": 63.748, "lines": ["agents au travail, avec un CGP", "qui garde la main à chaque étape."]}, {"start": 64.978, "end": 69.095, "lines": ["Précision avant de commencer :", "ceci est une simulation pédagogique."]}, {"start": 69.135, "end": 73.583, "lines": ["Le cabinet, les personnes,", "les dossiers et les chiffres sont fictifs."]}, {"start": 75.123, "end": 77.881, "lines": ["Notre cabinet fictif", "s'appelle Horizon Patrimoine."]}, {"start": 77.921, "end": 80.828, "lines": ["Il est installé à Aix-en-Provence", "et compte trois personnes."]}, {"start": 81.003, "end": 82.637, "lines": ["Sophie dirige le cabinet."]}, {"start": 82.677, "end": 84.669, "lines": ["Elle conduit les rendez-vous", "patrimoniaux,"]}, {"start": 84.669, "end": 88.335, "lines": ["prend les décisions de conseil et valide", "les communications importantes."]}, {"start": 88.425, "end": 89.717, "lines": ["Karim est conseiller."]}, {"start": 89.757, "end": 94.317, "lines": ["Il prépare les dossiers, suit une partie", "des clients et réalise des rendez-vous."]}, {"start": 94.407, "end": 96.584, "lines": ["Léa coordonne l'accueil, l'agenda,"]}, {"start": 96.584, "end": 99.961, "lines": ["les demandes de pièces", "et le suivi administratif."]}, {"start": 100.001, "end": 102.302, "lines": ["Elle travaille quatre", "jours par semaine."]}, {"start": 102.477, "end": 105.042, "lines": ["Dans notre simulation,", "le cabinet suit environ cent"]}, {"start": 105.042, "end": 109.064, "lines": ["quatre-vingts foyers clients et reçoit", "régulièrement de nouveaux prospects."]}, {"start": 109.154, "end": 113.701, "lines": ["On ne suppose aucun statut réglementaire", "unique : une vraie mission vérifierait"]}, {"start": 113.701, "end": 117.289, "lines": ["les statuts du cabinet,", "ses prestations et ses procédures."]}, {"start": 117.549, "end": 120.91, "lines": ["L'équipe utilise un CRM,", "une messagerie, un agenda,"]}, {"start": 120.91, "end": 124.511, "lines": ["un espace documentaire", "et des modèles de documents."]}, {"start": 124.551, "end": 126.177, "lines": ["Les outils existent."]}, {"start": 126.217, "end": 129.213, "lines": ["Le problème,", "ce sont les passages de l'un à l'autre."]}, {"start": 129.388, "end": 132.569, "lines": ["Avant un rendez-vous, Sophie", "retrouve une note dans le CRM,"]}, {"start": 132.569, "end": 135.965, "lines": ["cherche le dernier échange", "dans sa messagerie, ouvre les pièces"]}, {"start": 135.965, "end": 139.935, "lines": ["dans un dossier partagé et vérifie", "si une action promise a été faite."]}, {"start": 140.025, "end": 142.214, "lines": ["Après le rendez-vous,", "elle refait une partie"]}, {"start": 142.214, "end": 145.499, "lines": ["du chemin pour rédiger le compte", "rendu et organiser la suite."]}, {"start": 145.589, "end": 148.334, "lines": ["C'est sur ces passages", "de relais que porte notre audit."]}, {"start": 149.449, "end": 153.578, "lines": ["La mission commence avec les personnes,", "pas avec une démonstration d'IA."]}, {"start": 153.618, "end": 157.643, "lines": ["Pendant le diagnostic, on demande à chacun", "de montrer un dossier de bout en bout."]}, {"start": 157.683, "end": 159.213, "lines": ["Comment arrive une demande ?"]}, {"start": 159.253, "end": 160.859, "lines": ["Quelles sources sont consultées ?"]}, {"start": 160.899, "end": 162.68, "lines": ["Qui repère une pièce manquante ?"]}, {"start": 162.72, "end": 164.183, "lines": ["Qui valide le compte rendu ?"]}, {"start": 164.223, "end": 165.862, "lines": ["Où voit-on la prochaine action ?"]}, {"start": 166.037, "end": 168.011, "lines": ["On distingue ce que l'équipe", "déclare faire,"]}, {"start": 168.011, "end": 172.163, "lines": ["ce qu'on peut observer dans les outils, et", "ce qu'il faudra mesurer pendant le pilote."]}, {"start": 172.423, "end": 175.651, "lines": ["On répartit ensuite vingt-quatre", "heures hebdomadaires"]}, {"start": 175.651, "end": 180.373, "lines": ["de travail répétitif en trois blocs,", "sans compter deux fois la même tâche."]}, {"start": 180.413, "end": 182.559, "lines": ["Huit heures pour préparer", "les rendez-vous,"]}, {"start": 182.559, "end": 186.267, "lines": ["rassembler le contexte et remettre", "les notes en forme après l'échange."]}, {"start": 186.307, "end": 188.283, "lines": ["Neuf heures", "pour rechercher les pièces,"]}, {"start": 188.283, "end": 191.809, "lines": ["vérifier des listes de contrôle", "et préparer les revues de dossiers."]}, {"start": 191.849, "end": 194.059, "lines": ["Sept heures pour retrouver", "les engagements,"]}, {"start": 194.059, "end": 197.974, "lines": ["rédiger des brouillons de suivi", "et préparer les priorités de la semaine."]}, {"start": 198.014, "end": 200.729, "lines": ["Huit plus neuf plus sept :", "vingt-quatre heures."]}, {"start": 200.769, "end": 202.696, "lines": ["Ce sont des hypothèses de départ."]}, {"start": 202.736, "end": 205.066, "lines": ["Dans un vrai cabinet,", "il faudrait chronométrer"]}, {"start": 205.066, "end": 208.965, "lines": ["un échantillon de tâches et tenir", "compte des différences entre dossiers."]}, {"start": 209.31, "end": 213.388, "lines": ["On note aussi le fonctionnement du cabinet", "sur cinq critères, chacun sur vingt."]}, {"start": 213.428, "end": 215.667, "lines": ["Processus : treize sur vingt."]}, {"start": 215.707, "end": 218.875, "lines": ["L'équipe connaît les étapes,", "mais elles sont peu documentées."]}, {"start": 218.915, "end": 221.418, "lines": ["Interconnexion des outils :", "six sur vingt."]}, {"start": 221.458, "end": 224.484, "lines": ["Plusieurs informations doivent", "être recherchées et ressaisies."]}, {"start": 224.524, "end": 227.673, "lines": ["Maîtrise des accès et des données :", "sept sur vingt."]}, {"start": 227.713, "end": 230.963, "lines": ["Les règles d'usage des outils", "d'IA restent à préciser."]}, {"start": 231.003, "end": 233.807, "lines": ["Appropriation par l'équipe :", "neuf sur vingt."]}, {"start": 233.847, "end": 237.621, "lines": ["Chacun est intéressé, personne n'a", "encore testé un workflow complet."]}, {"start": 237.661, "end": 240.988, "lines": ["Validations et traçabilité :", "dix sur vingt."]}, {"start": 241.028, "end": 245.763, "lines": ["Les décisions humaines existent, mais", "leur historique est difficile à retrouver."]}, {"start": 245.853, "end": 248.165, "lines": ["Total : quarante-cinq sur cent."]}, {"start": 248.51, "end": 251.494, "lines": ["Ce n'est pas une mesure", "du professionnalisme des conseillers,"]}, {"start": 251.494, "end": 255.305, "lines": ["mais la photographie fictive d'un", "système de travail, selon notre grille."]}, {"start": 255.345, "end": 258.273, "lines": ["La mission devra rendre", "chaque critère vérifiable."]}, {"start": 258.618, "end": 260.007, "lines": ["On range ensuite les tâches"]}, {"start": 260.007, "end": 263.67, "lines": ["observées dans les cinq domaines", "de la cartographie Agentic Wealth."]}, {"start": 263.71, "end": 268.279, "lines": ["Acquisition et conversion : prospects,", "premiers rendez-vous, relances."]}, {"start": 268.319, "end": 272.126, "lines": ["Conseil et préparation : briefs,", "comptes rendus, questions à poser."]}, {"start": 272.166, "end": 277.467, "lines": ["Conformité et traçabilité : pièces, listes", "de contrôle, journaux de validation."]}, {"start": 277.507, "end": 282.323, "lines": ["Service et relation client :", "demandes entrantes, engagements, réponses."]}, {"start": 282.363, "end": 287.223, "lines": ["Pilotage du cabinet : priorités,", "échéances, dossiers sans action récente."]}, {"start": 287.313, "end": 291.582, "lines": ["Partout, la même règle :", "l'agent prépare, le conseiller décide."]}, {"start": 291.622, "end": 294.743, "lines": ["Voyons trois agents à l'œuvre,", "sur une semaine type."]}, {"start": 296.143, "end": 297.407, "lines": ["Première scène."]}, {"start": 297.447, "end": 299.58, "lines": ["Mardi, huit heures trente-cinq."]}, {"start": 299.62, "end": 302.93, "lines": ["Sophie a un rendez-vous de suivi", "à quatorze heures avec Camille,"]}, {"start": 302.93, "end": 304.215, "lines": ["une cliente fictive."]}, {"start": 304.305, "end": 308.009, "lines": ["Sans agent, elle ouvre le CRM,", "cherche le dernier compte rendu,"]}, {"start": 308.009, "end": 312.131, "lines": ["relit trois échanges, vérifie", "les documents et note ses questions."]}, {"start": 312.171, "end": 316.201, "lines": ["Après le rendez-vous, elle rédige", "le compte rendu et crée les actions."]}, {"start": 316.241, "end": 319.323, "lines": ["Cette chaîne pèse lourd", "dans les huit heures du premier bloc."]}, {"start": 319.498, "end": 323.595, "lines": ["Voici le parcours à tester : onze étapes,", "dont trois validations humaines."]}, {"start": 323.77, "end": 326.676, "lines": ["Étape un : Sophie sélectionne", "elle-même le rendez-vous."]}, {"start": 326.716, "end": 328.676, "lines": ["L'agent ne choisit", "pas seul les dossiers."]}, {"start": 328.766, "end": 332.318, "lines": ["Étape deux : elle autorise", "les sources utiles pour ce dossier :"]}, {"start": 332.318, "end": 336.266, "lines": ["fiche CRM, comptes rendus validés,", "échanges professionnels pertinents,"]}, {"start": 336.266, "end": 339.188, "lines": ["documents auxquels elle", "est habilitée à accéder."]}, {"start": 339.228, "end": 343.037, "lines": ["Une archive ancienne et la messagerie", "complète restent grisées :"]}, {"start": 343.037, "end": 344.834, "lines": ["elles sont hors périmètre."]}, {"start": 344.924, "end": 346.946, "lines": ["Étape trois : la collecte."]}, {"start": 346.986, "end": 350.815, "lines": ["L'agent ne lit que ces sources,", "et garde l'origine de chaque information."]}, {"start": 350.855, "end": 352.998, "lines": ["Étape quatre : le rapprochement."]}, {"start": 353.038, "end": 356.314, "lines": ["La fiche CRM indique", "une dernière revue le douze mars,"]}, {"start": 356.314, "end": 358.981, "lines": ["le compte rendu validé", "le quatorze mars."]}, {"start": 359.021, "end": 361.926, "lines": ["L'agent ne choisit pas :", "il signale l'écart."]}, {"start": 362.016, "end": 364.063, "lines": ["Étape cinq : les manques."]}, {"start": 364.103, "end": 366.923, "lines": ["Un justificatif introuvable,", "une échéance citée"]}, {"start": 366.923, "end": 371.663, "lines": ["dans un échange mais absente du suivi,", "une information vieille de deux ans."]}, {"start": 371.703, "end": 373.913, "lines": ["Chaque point est listé", "avec sa source."]}, {"start": 374.003, "end": 375.961, "lines": ["Étape six : le brief."]}, {"start": 376.001, "end": 378.831, "lines": ["En haut, les faits sourcés :", "dernier échange,"]}, {"start": 378.831, "end": 383.851, "lines": ["objectifs exprimés par la cliente,", "actions convenues, documents disponibles."]}, {"start": 383.891, "end": 385.947, "lines": ["Plus bas, les points à vérifier."]}, {"start": 385.987, "end": 387.857, "lines": ["Puis des questions", "pour l'entretien,"]}, {"start": 387.857, "end": 390.506, "lines": ["comme : « L'objectif formulé", "au dernier rendez-vous"]}, {"start": 390.506, "end": 394.174, "lines": ["est-il toujours d'actualité ? »", "Une question aide la conversation."]}, {"start": 394.214, "end": 396.88, "lines": ["Elle ne conclut rien", "sur la situation de Camille."]}, {"start": 396.97, "end": 399.09, "lines": ["Étape sept : la correction."]}, {"start": 399.13, "end": 401.13, "lines": ["Sophie voit d'où", "vient chaque élément."]}, {"start": 401.17, "end": 405.314, "lines": ["Elle retire une question peu pertinente,", "corrige la date de la dernière revue,"]}, {"start": 405.314, "end": 406.776, "lines": ["puis valide sa version."]}, {"start": 406.816, "end": 410.252, "lines": ["C'est Sophie qui mène le rendez-vous", "et interprète les réponses."]}, {"start": 410.427, "end": 414.252, "lines": ["Étape huit : le rendez-vous,", "de quatorze heures à quinze heures dix."]}, {"start": 414.292, "end": 415.348, "lines": ["Pas d'écran d'IA :"]}, {"start": 415.348, "end": 419.12, "lines": ["la conversation appartient", "à la cliente et à sa conseillère."]}, {"start": 419.465, "end": 422.449, "lines": ["Étape neuf :", "le brouillon de compte rendu."]}, {"start": 422.489, "end": 425.098, "lines": ["À quinze heures dix,", "Sophie saisit ses notes,"]}, {"start": 425.098, "end": 428.734, "lines": ["ou une transcription si celle-ci", "est autorisée et encadrée."]}, {"start": 428.774, "end": 432.23, "lines": ["L'agent sépare quatre choses :", "les faits rapportés par la cliente,"]}, {"start": 432.23, "end": 433.435, "lines": ["les questions ouvertes,"]}, {"start": 433.435, "end": 437.263, "lines": ["les décisions réellement prises", "par Sophie, et les actions proposées."]}, {"start": 437.303, "end": 440.839, "lines": ["Il signale une phrase ambiguë :", "« revoir le dossier le mois prochain »."]}, {"start": 440.879, "end": 443.59, "lines": ["Revoir quoi, avec qui,", "à quelle date ?"]}, {"start": 443.63, "end": 445.924, "lines": ["Il ne complète pas", "la promesse de lui-même."]}, {"start": 446.014, "end": 448.189, "lines": ["Étape dix : la validation."]}, {"start": 448.229, "end": 451.619, "lines": ["Sophie précise : un point", "téléphonique dans quatre semaines,"]}, {"start": 451.619, "end": 453.272, "lines": ["qu'elle mènera elle-même."]}, {"start": 453.312, "end": 454.986, "lines": ["Puis elle valide le compte rendu."]}, {"start": 455.076, "end": 457.88, "lines": ["Étape onze :", "les tâches et le suivi."]}, {"start": 457.92, "end": 462.228, "lines": ["L'agent propose deux tâches,", "avec responsable et échéance à confirmer."]}, {"start": 462.268, "end": 466.277, "lines": ["Une fois validées par Sophie, elles", "rejoignent l'outil de suivi autorisé."]}, {"start": 466.317, "end": 468.884, "lines": ["Un message à Camille", "reste un brouillon."]}, {"start": 468.924, "end": 472.313, "lines": ["Sophie contrôle le destinataire,", "le contenu et l'envoi."]}, {"start": 472.353, "end": 474.096, "lines": ["Rien ne part sans son clic."]}, {"start": 474.271, "end": 479.1, "lines": ["Sur les huit heures de ce bloc, l'objectif", "de test est d'en récupérer quatre."]}, {"start": 479.14, "end": 481.555, "lines": ["C'est un gain cible,", "pas un résultat."]}, {"start": 481.595, "end": 483.455, "lines": ["On mesurera le temps", "avant et après,"]}, {"start": 483.455, "end": 486.821, "lines": ["les corrections, les erreurs,", "et l'utilité réelle des briefs."]}, {"start": 486.861, "end": 491.764, "lines": ["Premier jalon, volontairement petit :", "trois briefs, puis une décision de Sophie."]}, {"start": 491.804, "end": 494.609, "lines": ["Continuer, ajuster,", "ou retirer l'accès."]}, {"start": 496.009, "end": 497.296, "lines": ["Deuxième scène."]}, {"start": 497.336, "end": 498.821, "lines": ["Mercredi, dix heures vingt."]}, {"start": 498.861, "end": 503.094, "lines": ["Léa prépare plusieurs dossiers pour des", "rendez-vous et une revue périodique."]}, {"start": 503.134, "end": 507.048, "lines": ["Elle parcourt les répertoires, compare", "les fichiers aux listes du cabinet,"]}, {"start": 507.048, "end": 511.231, "lines": ["cherche des dates, et fait trancher", "les cas incertains par Sophie ou Karim."]}, {"start": 511.271, "end": 515.244, "lines": ["Dans notre simulation, ce travail", "représente neuf heures par semaine."]}, {"start": 515.419, "end": 518.805, "lines": ["Première limite : l'agent n'invente", "pas les règles de contrôle."]}, {"start": 518.845, "end": 522.977, "lines": ["La liste applicable vient du cabinet,", "validée par la personne compétente."]}, {"start": 523.017, "end": 526.391, "lines": ["On vérifie aussi le cadre d'accès", "aux données : quelles sources,"]}, {"start": 526.391, "end": 528.816, "lines": ["quelles personnes habilitées,", "quelle finalité,"]}, {"start": 528.816, "end": 531.65, "lines": ["quel sous-traitant éventuel,", "quelle conservation."]}, {"start": 531.825, "end": 535.266, "lines": ["Pour un dossier sélectionné,", "l'agent lit la liste approuvée,"]}, {"start": 535.266, "end": 537.846, "lines": ["inventorie seulement", "les documents autorisés,"]}, {"start": 537.846, "end": 542.856, "lines": ["et range chaque ligne en quatre colonnes :", "présent, absent, ambigu, ou non vérifié."]}, {"start": 543.031, "end": 547.331, "lines": ["Supposons un justificatif présent,", "mais dont la date est illisible."]}, {"start": 547.371, "end": 550.145, "lines": ["L'agent ne le marque ni", "« valide », ni « périmé »."]}, {"start": 550.185, "end": 551.446, "lines": ["Il le classe en ambigu,"]}, {"start": 551.446, "end": 554.895, "lines": ["et montre le document source", "avec la raison du signalement."]}, {"start": 554.935, "end": 558.858, "lines": ["Léa retrouve une meilleure version,", "ou demande à Sophie quelle suite donner."]}, {"start": 559.033, "end": 562.605, "lines": ["Pour une revue périodique,", "il compare avec la dernière revue :"]}, {"start": 562.605, "end": 566.967, "lines": ["éléments nouveaux, inchangés,", "pièces à examiner, contrôles sans réponse."]}, {"start": 567.007, "end": 569.568, "lines": ["Si une information", "essentielle manque,"]}, {"start": 569.568, "end": 572.705, "lines": ["l'écran indique :", "décision humaine requise."]}, {"start": 572.745, "end": 576.837, "lines": ["Jamais de badge « dossier conforme »", "sur la seule base de sa lecture."]}, {"start": 577.012, "end": 580.535, "lines": ["C'est essentiel pour la connaissance", "client et la vigilance."]}, {"start": 580.575, "end": 582.175, "lines": ["Selon les activités exercées,"]}, {"start": 582.175, "end": 585.755, "lines": ["le professionnel applique", "les exigences qui lui sont propres."]}, {"start": 585.795, "end": 589.377, "lines": ["Pour le conseil en investissements", "financiers, l'AMF décrit notamment"]}, {"start": 589.377, "end": 592.907, "lines": ["les informations à recueillir avant", "de conseiller, et la déclaration"]}, {"start": 592.907, "end": 597.144, "lines": ["d'adéquation remise au client avant", "la réalisation de l'opération conseillée."]}, {"start": 597.184, "end": 598.92, "lines": ["Pour les professionnels", "assujettis,"]}, {"start": 598.92, "end": 602.756, "lines": ["les obligations de vigilance suivent", "une approche fondée sur les risques."]}, {"start": 602.796, "end": 605.561, "lines": ["L'agent aide à préparer", "et à retrouver des éléments,"]}, {"start": 605.561, "end": 607.556, "lines": ["sans statuer sur leur suffisance."]}, {"start": 607.596, "end": 612.007, "lines": ["Et cette vidéo n'est pas un modèle", "universel de dossier réglementaire."]}, {"start": 612.182, "end": 616.17, "lines": ["Après la revue, un journal conserve", "les sources consultées, la version"]}, {"start": 616.17, "end": 620.443, "lines": ["du résultat, la correction de Léa,", "la validation de Sophie et l'horodatage,"]}, {"start": 620.443, "end": 623.165, "lines": ["selon les règles", "de conservation du cabinet."]}, {"start": 623.205, "end": 625.824, "lines": ["Mais un journal technique", "n'est pas, à lui seul,"]}, {"start": 625.824, "end": 629.293, "lines": ["la preuve que les obligations", "réglementaires sont remplies."]}, {"start": 629.468, "end": 632.779, "lines": ["Hypothèse : ramener ce bloc", "de neuf à six heures par semaine,"]}, {"start": 632.779, "end": 634.568, "lines": ["soit trois heures récupérées."]}, {"start": 634.608, "end": 638.179, "lines": ["Le pilote suivra aussi les faux positifs,", "les vrais manques détectés,"]}, {"start": 638.179, "end": 641.069, "lines": ["et les situations correctement", "laissées à l'équipe."]}, {"start": 642.469, "end": 643.646, "lines": ["Troisième scène."]}, {"start": 643.686, "end": 645.657, "lines": ["Jeudi, seize heures quarante."]}, {"start": 645.697, "end": 646.557, "lines": ["Une cliente écrit :"]}, {"start": 646.557, "end": 649.941, "lines": ["« Pouvez-vous me rappeler ce que nous", "avions convenu pour la suite ? »"]}, {"start": 649.981, "end": 653.143, "lines": ["Léa cherche le dernier compte", "rendu, vérifie la tâche,"]}, {"start": 653.143, "end": 655.901, "lines": ["puis demande à Karim", "si l'action est faite."]}, {"start": 655.941, "end": 660.124, "lines": ["En parallèle, un prospect attend", "un retour et deux échéances approchent."]}, {"start": 660.214, "end": 662.366, "lines": ["L'agent de service", "classe la demande,"]}, {"start": 662.366, "end": 665.682, "lines": ["puis rassemble les seuls", "éléments autorisés : le message,"]}, {"start": 665.682, "end": 668.632, "lines": ["le compte rendu validé,", "la tâche et son statut."]}, {"start": 668.672, "end": 670.111, "lines": ["Il prépare une fiche."]}, {"start": 670.151, "end": 671.864, "lines": ["Voici l'engagement retrouvé."]}, {"start": 671.904, "end": 673.328, "lines": ["Voici sa source."]}, {"start": 673.368, "end": 674.753, "lines": ["Voici l'état connu."]}, {"start": 674.793, "end": 676.886, "lines": ["Et voici ce que nous", "ne savons pas encore."]}, {"start": 676.976, "end": 679.262, "lines": ["Il peut rédiger", "un brouillon de réponse."]}, {"start": 679.302, "end": 681.375, "lines": ["Ici, la tâche n'a pas", "de statut fiable :"]}, {"start": 681.375, "end": 684.338, "lines": ["le brouillon n'affirme donc", "pas qu'elle est terminée."]}, {"start": 684.378, "end": 687.647, "lines": ["Karim vérifie, complète,", "puis décide de l'envoi."]}, {"start": 687.687, "end": 690.878, "lines": ["Seul Karim dispose du bouton", "« vérifier et envoyer »."]}, {"start": 690.918, "end": 693.28, "lines": ["L'agent n'a qu'un bouton :", "« préparer »."]}, {"start": 693.455, "end": 695.301, "lines": ["Même logique pour un prospect."]}, {"start": 695.341, "end": 698.094, "lines": ["L'agent propose une fiche", "de qualification à partir"]}, {"start": 698.094, "end": 702.574, "lines": ["du formulaire et des échanges autorisés,", "des questions pour un premier rendez-vous,"]}, {"start": 702.574, "end": 704.408, "lines": ["et une relance contextualisée."]}, {"start": 704.448, "end": 706.512, "lines": ["Le conseiller choisit", "de prendre contact,"]}, {"start": 706.512, "end": 709.722, "lines": ["d'accepter ou non le prospect,", "et d'envoyer chaque message."]}, {"start": 709.762, "end": 712.425, "lines": ["Aucun score automatique", "de « valeur » de la personne."]}, {"start": 712.685, "end": 716.957, "lines": ["Le lundi suivant, à neuf heures,", "Sophie ouvre une vue de pilotage."]}, {"start": 716.997, "end": 721.145, "lines": ["L'agent a rapproché agenda, tâches", "et statuts du CRM en quatre listes :"]}, {"start": 721.145, "end": 724.768, "lines": ["rendez-vous à préparer,", "engagements sans responsable confirmé,"]}, {"start": 724.768, "end": 725.994, "lines": ["échéances à vérifier,"]}, {"start": 725.994, "end": 730.416, "lines": ["et dossiers sans action récente,", "selon une règle choisie par le cabinet."]}, {"start": 730.456, "end": 732.486, "lines": ["Chaque signal comporte une raison."]}, {"start": 732.526, "end": 737.058, "lines": ["Un dossier sans activité récente", "n'est pas étiqueté « client négligé »."]}, {"start": 737.098, "end": 740.188, "lines": ["Sophie répond : « celui-ci", "attend volontairement une date »,"]}, {"start": 740.188, "end": 743.981, "lines": ["« celui-là mérite un appel »,", "« cette donnée du CRM est incorrecte »."]}, {"start": 744.021, "end": 745.552, "lines": ["C'est elle qui arbitre."]}, {"start": 745.727, "end": 749.253, "lines": ["Notre hypothèse : ramener ce bloc", "de sept à quatre heures par semaine,"]}, {"start": 749.253, "end": 750.928, "lines": ["soit trois heures récupérées."]}, {"start": 750.968, "end": 753.475, "lines": ["On compte aussi les alertes", "utiles ou écartées,"]}, {"start": 753.475, "end": 756.542, "lines": ["les brouillons corrigés", "et les engagements retrouvés."]}, {"start": 756.582, "end": 759.759, "lines": ["Si le tableau produit du bruit,", "on réduit son périmètre :"]}, {"start": 759.759, "end": 762.796, "lines": ["un cockpit que personne", "n'ouvre n'est pas un gain."]}, {"start": 764.196, "end": 767.279, "lines": ["Sophie pose alors la bonne question :", "« Pour préparer tout ça,"]}, {"start": 767.279, "end": 770.512, "lines": ["l'agent doit-il lire tous mes", "mails et tous mes dossiers ? »"]}, {"start": 770.602, "end": 772.632, "lines": ["La réponse de la mission est non."]}, {"start": 772.807, "end": 775.027, "lines": ["Chaque workflow", "a un objectif défini,"]}, {"start": 775.027, "end": 779.528, "lines": ["des sources approuvées, des droits", "limités et des personnes habilitées."]}, {"start": 779.568, "end": 782.548, "lines": ["Source autorisée,", "accès limité, préparation,"]}, {"start": 782.548, "end": 785.644, "lines": ["validation humaine,", "destination autorisée."]}, {"start": 785.734, "end": 787.924, "lines": ["Avant d'utiliser", "des données clients,"]}, {"start": 787.924, "end": 792.365, "lines": ["le cabinet examine ses responsabilités,", "ses contrats avec les prestataires,"]}, {"start": 792.365, "end": 795.955, "lines": ["la sécurité, la conservation", "et les éventuels transferts."]}, {"start": 795.995, "end": 799.453, "lines": ["Héberger un modèle soi-même,", "ou choisir un modèle open source,"]}, {"start": 799.453, "end": 802.259, "lines": ["ne suffit pas à rendre", "un traitement conforme."]}, {"start": 802.299, "end": 805.536, "lines": ["La CNIL rappelle notamment l'importance", "d'encadrer la sous-traitance,"]}, {"start": 805.536, "end": 809.07, "lines": ["de protéger les données et de garder", "une intervention humaine adaptée."]}, {"start": 809.245, "end": 811.331, "lines": ["Concrètement,", "l'agent sait s'arrêter."]}, {"start": 811.371, "end": 815.986, "lines": ["S'il ne retrouve pas la source d'un fait,", "il écrit : information non vérifiée."]}, {"start": 816.026, "end": 819.345, "lines": ["Si une pièce est illisible,", "il demande une vérification."]}, {"start": 819.385, "end": 824.027, "lines": ["Si une demande implique une interprétation", "patrimoniale ou une décision de conseil,"]}, {"start": 824.027, "end": 825.507, "lines": ["il la transmet au CGP."]}, {"start": 825.597, "end": 827.58, "lines": ["Il ne recommande aucun produit."]}, {"start": 827.62, "end": 830.329, "lines": ["Il ne détermine pas seul", "un profil de risque."]}, {"start": 830.369, "end": 832.622, "lines": ["Il ne déclare pas", "un dossier conforme."]}, {"start": 832.662, "end": 834.933, "lines": ["Il ne contacte personne", "automatiquement."]}, {"start": 834.973, "end": 837.932, "lines": ["Il ne modifie pas un engagement", "client sans validation."]}, {"start": 838.107, "end": 839.235, "lines": ["C'est pourquoi un vrai"]}, {"start": 839.235, "end": 843.267, "lines": ["déploiement commence avec des données", "de démonstration et un accès limité."]}, {"start": 843.307, "end": 844.304, "lines": ["Les données réelles"]}, {"start": 844.304, "end": 848.65, "lines": ["arrivent seulement après revue du cadre", "applicable et autorisation du cabinet."]}, {"start": 850.05, "end": 853.897, "lines": ["Reprenons nos chiffres, sans additionner", "des promesses incompatibles."]}, {"start": 853.987, "end": 858.124, "lines": ["Préparation des rendez-vous et suivi :", "huit heures avant, quatre visées après."]}, {"start": 858.164, "end": 859.517, "lines": ["Quatre heures à confirmer."]}, {"start": 859.557, "end": 862.657, "lines": ["Contrôles et revues :", "neuf heures avant, six visées."]}, {"start": 862.697, "end": 864.089, "lines": ["Trois heures à confirmer."]}, {"start": 864.129, "end": 868.696, "lines": ["Relation client et pilotage :", "sept heures avant, quatre visées."]}, {"start": 868.736, "end": 870.163, "lines": ["Trois heures à confirmer."]}, {"start": 870.253, "end": 873.588, "lines": ["Avant : huit plus neuf plus sept,", "vingt-quatre heures."]}, {"start": 873.628, "end": 876.873, "lines": ["Après, visé : quatre plus six", "plus quatre, quatorze heures."]}, {"start": 876.913, "end": 879.697, "lines": ["L'écart visé :", "dix heures par semaine."]}, {"start": 879.787, "end": 881.558, "lines": ["Dix heures de capacité", "potentielle,"]}, {"start": 881.558, "end": 884.428, "lines": ["à condition que les gains", "résistent à l'observation."]}, {"start": 884.468, "end": 886.618, "lines": ["La mesure réelle reste à établir."]}, {"start": 886.708, "end": 888.48, "lines": ["Sur une année,", "dix heures multipliées"]}, {"start": 888.48, "end": 892.273, "lines": ["par quarante-six semaines travaillées", "donnent quatre cent soixante heures."]}, {"start": 892.363, "end": 894.097, "lines": ["À titre d'illustration seulement,"]}, {"start": 894.097, "end": 897.777, "lines": ["avec une heure interne valorisée", "à soixante euros, cela représenterait"]}, {"start": 897.777, "end": 901.391, "lines": ["vingt-sept mille six cents euros", "de capacité théorique annuelle."]}, {"start": 901.481, "end": 905.927, "lines": ["Ce n'est ni une économie de trésorerie", "acquise, ni un revenu additionnel."]}, {"start": 905.967, "end": 906.974, "lines": ["Capacité théorique,"]}, {"start": 906.974, "end": 911.055, "lines": ["économies encaissées et chiffre", "d'affaires sont trois choses différentes."]}, {"start": 911.095, "end": 913.654, "lines": ["Il faut encore déduire", "le temps de contrôle humain,"]}, {"start": 913.654, "end": 916.965, "lines": ["le coût des outils, la maintenance", "et les erreurs à corriger."]}, {"start": 918.365, "end": 920.163, "lines": ["Quel agent déployer en premier ?"]}, {"start": 920.203, "end": 923.311, "lines": ["Ici, je commencerais", "par la préparation d'un rendez-vous,"]}, {"start": 923.311, "end": 927.888, "lines": ["sur trois briefs : un périmètre étroit,", "compréhensible par Sophie, et mesurable."]}, {"start": 927.928, "end": 930.736, "lines": ["Si les briefs sont utiles", "et les accès maîtrisés,"]}, {"start": 930.736, "end": 934.976, "lines": ["on ajoute le compte rendu et les tâches,", "puis les contrôles documentaires,"]}, {"start": 934.976, "end": 937.633, "lines": ["et enfin la relation", "client et le cockpit."]}, {"start": 937.808, "end": 939.677, "lines": ["Voici le planning proposé."]}, {"start": 939.717, "end": 941.995, "lines": ["Semaines un et deux :", "diagnostic réel,"]}, {"start": 941.995, "end": 946.526, "lines": ["chronométrage, cartographie des données,", "et choix d'un seul cas d'usage."]}, {"start": 946.566, "end": 950.552, "lines": ["Semaines trois à cinq :", "construction et test du premier workflow,"]}, {"start": 950.552, "end": 954.778, "lines": ["d'abord sur des données fictives,", "puis sur un périmètre autorisé."]}, {"start": 954.818, "end": 957.68, "lines": ["Trois briefs,", "relus intégralement par Sophie."]}, {"start": 957.72, "end": 962.163, "lines": ["Semaines six à huit : décision", "d'étendre, d'ajuster ou d'arrêter."]}, {"start": 962.203, "end": 965.924, "lines": ["Les autres agents n'entrent dans le pilote", "que si le premier a fait ses preuves"]}, {"start": 965.924, "end": 967.693, "lines": ["et si leurs accès sont approuvés."]}, {"start": 967.733, "end": 971.544, "lines": ["Huit semaines ne promettent donc pas trois", "agents achevés dans tous les cabinets."]}, {"start": 971.889, "end": 974.414, "lines": ["Le résultat recherché", "n'est pas un cabinet"]}, {"start": 974.414, "end": 978.381, "lines": ["où l'intelligence artificielle", "parle à la place du conseiller."]}, {"start": 978.421, "end": 982.045, "lines": ["C'est un cabinet où le conseiller", "retrouve le contexte, voit les manques,"]}, {"start": 982.045, "end": 984.578, "lines": ["et décide avec moins", "de recherches dispersées."]}, {"start": 984.838, "end": 987.895, "lines": ["Si vous dirigez un cabinet", "de gestion de patrimoine,"]}, {"start": 987.895, "end": 989.717, "lines": ["le point de départ est simple :"]}, {"start": 989.717, "end": 992.636, "lines": ["montrez-nous un dossier", "et une semaine réelle."]}, {"start": 992.676, "end": 996.377, "lines": ["On identifiera ce qui mérite d'être", "préparé, ce qui doit rester humain,"]}, {"start": 996.377, "end": 999.389, "lines": ["et ce qu'un pilote permettrait", "réellement de mesurer."]}, {"start": 999.819, "end": 1001.325, "lines": ["Agentic Wealth."]}, {"start": 1001.365, "end": 1002.58, "lines": ["L'agent prépare."]}, {"start": 1002.62, "end": 1004.988, "lines": ["Le CGP valide et décide."]}], "duration": 1007.713};
